const body = $input.first().json.body || $input.first().json;
const rawNiche = body.niche || 'trending';
const niche = rawNiche.split(',')[0].trim().toLowerCase().replace(/#/g, '');

const mapping = {
  'fashion': ['vogue', 'ellemagazine', 'gq'],
  'fitness': ['gymshark', 'nike', 'adidas'],
  'fitness_female': ['gymsharkwomen', 'alo'],
  'tech': ['marquesbrownlee', 'theverge', 'techcrunch'],
  'food': ['buzzfeedtasty', 'foodnetwork'],
  'travel': ['beautifuldestinations', 'natgeotravel'],
  'luxury': ['luxuryworldtraveler', 'millionaire.lifestyle'],
  'business': ['forbes', 'entrepreneur', 'businessinsider'],
  'gaming': ['ign', 'gamespot', 'twitch'],
  'cars': ['topgear', 'caranddriver', 'supercarblondie'],
  'architecture': ['archdigest', 'dezeen']
};

const targetAccounts = mapping[niche] || [niche];
return [{ json: { niche, targetAccounts } }];

const allItems = $input.all();
const niche = $('⚙️ Extract Instagram Niche').item.json.niche;
const results = [];
for (let i = 0; i < Math.min(10, allItems.length); i++) {
  const d = allItems[i].json;
  const caption = (d.caption || d.alt || d.title || 'Trending Post').substring(0, 300);
  const hashtags = (caption.match(/#\w+/g) || []).slice(0, 10);
  results.push({ json: {
    rank: i + 1,
    video_id: String(d.shortCode || d.id || d.pk || i),
    title: caption,
    author: '@' + (d.ownerUsername || d.owner?.username || 'unknown'),
    views: String(d.videoViewCount || d.videoPlayCount || d.view_count || 0),
    likes: String(d.likesCount || d.like_count || 0),
    video_url: d.videoUrl || d.video_url || '',
    hashtags: hashtags.length ? hashtags : ['#' + niche],
    category: niche.slice(0, 100),
    thumbnail_url: (d.displayUrl || d.thumbnailUrl || '').slice(0, 1000),
    tiktok_url: 'https://www.instagram.com/p/' + (d.shortCode || d.code || '') + '/'
  }});
}
return results;

const body = $input.first().json.body || $input.first().json;
return [{
  json: {
    niche: body.niche || 'general',
    selectedVideoId: body.video_id || body.selectedVideoId || '',
    videoTitle: body.title || body.videoTitle || '',
    creatorId: String(body.creator_id || body.creatorId || ''),
    userPrompt: body.custom_prompt || body.userPrompt || '',
    style: body.style || 'Dramatic',
    duration: body.duration || '30s'
  }
}];

const sessionData = $('🗄️ Create Instagram Session in DB').item.json;
const trendData = $input.first().json;
const inputData = $('⚙️ Extract Instagram Workflow Input').item.json;
const hashtagStr = Array.isArray(trendData.hashtags) ? trendData.hashtags.join(', ') : (trendData.hashtags || '');
const videoContext = trendData.title
  ? 'Title: "' + trendData.title + '"\nCreator: ' + trendData.author + '\nHashtags: ' + hashtagStr + '\nViews: ' + trendData.views + ' | Likes: ' + trendData.likes
  : 'Video ID: ' + sessionData.selected_video_id;
return [{
  json: {
    sessionId: sessionData.session_id,
    creatorId: sessionData.creator_id,
    niche: sessionData.niche,
    userPrompt: sessionData.user_prompt || '',
    videoContext,
    style: inputData.style || 'Dramatic'
  }
}];

const agentOutput = $input.first().json.output || $input.first().json.text || '';
const sessionData = $('🗄️ Create Instagram Session in DB').item.json;
let scriptJson = {};
try {
  const jsonMatch = agentOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) { scriptJson = JSON.parse(jsonMatch[0]); }
} catch(e) { scriptJson = { full_script: agentOutput }; }
const scriptContent = scriptJson.full_script || agentOutput;
const scriptContentSql = scriptContent.replace(/'/g, "''");
const scriptJsonSql = JSON.stringify(scriptJson).replace(/'/g, "''");
return [{
  json: {
    scriptId: 'ig_script_' + Date.now(),
    sessionId: sessionData.session_id || '',
    creatorId: sessionData.creator_id || '',
    scriptContent,
    scriptContentSql,
    scriptJson: scriptJsonSql,
    hook: scriptJson.hook || '',
    cta: scriptJson.cta || '',
    hashtags: scriptJson.hashtags || [],
    visual_directions: scriptJson.visual_directions || '',
    music_vibe: scriptJson.music_vibe || ''
  }
}];

const prepData = $('⚙️ Prepare Video Prompt').item.json;
const scriptData = $('⚙️ Parse Instagram Script Response').item.json;
const niche = $('🗄️ Create Instagram Session in DB').item.json.niche || 'trending';
let keywords = niche;
if (scriptData.hook) {
  keywords += ' ' + scriptData.hook.replace(/[^a-zA-Z0-9\s]/g, ' ');
}
keywords = keywords.substring(0, 80).trim();
return [{
  json: {
    keywords,
    scriptContent: scriptData.scriptContent || '',
    videoPrompt: prepData.videoPrompt || '',
    sessionId: prepData.sessionId,
    creatorId: prepData.creatorId
  }
}];

const mixOutput = $input.first().json;
const prepData = $('⚙️ Prepare Video Prompt').item.json;
const videoUrl = mixOutput.video_url || '';
return [{
  json: {
    videoId: 'ig_video_' + Date.now(),
    videoUrl,
    sessionId: prepData.sessionId || '',
    creatorId: prepData.creatorId || '',
    promptUsed: (prepData.videoPrompt || 'Pexels stock video + TTS').replace(/'/g, "''")
  }
}];

