const videoData = $('🗄️ Mark Instagram Video Approved').item.json;
const scriptData = $input.first().json;
let scriptJson = {};
try { scriptJson = JSON.parse(scriptData.script_json || '{}'); } catch(e) {}
const hashtags = scriptJson.hashtags || ['#reels', '#viral', '#trending'];
const hashtagStr = Array.isArray(hashtags) ? hashtags.join(' ') : hashtags;
const caption = (scriptJson.hook || 'Check this out! 🔥') + '\n\n' + hashtagStr;
return [{
  json: {
    caption,
    videoUrl: videoData.video_url,
    sessionId: videoData.session_id,
    creatorId: videoData.creator_id
  }
}];

const scriptData = $('⚙️ Parse Instagram Script Response').item.json;
const videoPrompt = 'Create a 15-second vertical Instagram Reel video. ' +
  'Hook: ' + (scriptData.hook || 'Engaging opening') + '. ' +
  'Main content: ' + (scriptData.scriptContent || 'Dynamic content').substring(0, 200) + '. ' +
  'Visual directions: ' + (scriptData.visual_directions || 'Eye-catching, fast-paced visuals') + '. ' +
  'Music vibe: ' + (scriptData.music_vibe || 'Upbeat trending audio') + '. ' +
  'Style: Social media optimized, 9:16 vertical format';
return [{
  json: {
    videoPrompt,
    sessionId: scriptData.sessionId,
    creatorId: scriptData.creatorId
  }
}];
